// Aggregate the expired rows into a single bulk delete.
// `Find Expired Documents` runs with alwaysOutputData, so an empty result
// arrives as one empty item rather than as no items at all.
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id && r.storage_path);

if (rows.length === 0) return [];   // nothing due -- stop this branch quietly

// `pairs` is the reconciliation ledger read by `Reconcile Storage Deletions`:
// each id sits beside the path whose deletion must be CONFIRMED before that id
// may be marked purged. `ids` is kept only for reference in the audit trail --
// nothing PATCHes by it any more. PATCHing that unconditional list is precisely
// what stamped purged_at on 500 rows for a delete that removed 250.
//
// TENANCY (2 Sep 2026). The purge itself stays a PLATFORM-WIDE sweep and should:
// retention is decided per ROW by retain_until, every row already carries its
// own owner, and kyc_documents ids are unique, so nothing here can delete
// across a dealership boundary. What DOES have an owner is the EVIDENCE. The
// audit row names the storage paths of documents that were not deleted, so one
// row spanning two dealerships would put one dealership's customer file paths
// on the other's Automation screen. `tenantByPath` lets `Summarise Purge` split
// that evidence and write ONE ROW PER DEALERSHIP -- iterating tenants rather
// than resolving one, which is the right shape for a sweep.
const tenantByPath = {};
const tenantById = {};
const tenants = [];
for (const r of rows) {
  const t = r.tenant_id || null;
  tenantByPath[String(r.storage_path)] = t;
  tenantById[String(r.id)] = t;
  if (tenants.indexOf(t) === -1) tenants.push(t);
}

return [{ json: {
  count: rows.length,
  ids: rows.map(r => r.id),
  paths: rows.map(r => r.storage_path),
  pairs: rows.map(r => ({ id: r.id, path: r.storage_path, tenant_id: r.tenant_id || null })),
  tenantByPath: tenantByPath,
  tenantById: tenantById,
  tenants: tenants,
  oldest_due: rows.map(r => r.retain_until).sort()[0],
} }];

// One audit row per purge run PER DEALERSHIP. A retention policy you cannot
// evidence is not a retention policy -- and a row that says 500 when 3 were
// deleted is worse than no row at all, because it is the document a regulator
// would be handed. From 2 Sep 2026 the same is true across dealerships: a row
// that names another dealership's customer document paths is not evidence, it
// is a leak. So this node ITERATES TENANTS and partitions the ledger by owner.
//
// Reach back to `Reconcile Storage Deletions` explicitly. $json is NOT safe
// here: this node is fed by two edges -- `Mark Rows Purged` (whose output is the
// PATCH response, empty under Prefer: return=minimal) when something was
// confirmed deleted, and `Anything Confirmed Deleted?` output 1 when nothing was.
const r    = $('Reconcile Storage Deletions').first().json || {};
const plan = $('Collect Expired Paths').first().json || {};

const tenantByPath = plan.tenantByPath || {};
const pairs = Array.isArray(plan.pairs) ? plan.pairs : [];

// ---- partition the ledger by owner -----------------------------------------
const byTenant = {};
function bucket(t) {
  const key = t || '__unresolved__';
  if (!byTenant[key]) byTenant[key] = { tenant_id: t || null, requested: 0, deleted: 0, unaccounted_paths: [] };
  return byTenant[key];
}
function ownerOfPath(p) { return tenantByPath[String(p)] || null; }

for (const p of pairs) {
  const t = (p && p.tenant_id) || ownerOfPath(p && p.path);
  bucket(t).requested++;
}
for (const p of (r.confirmed_paths || [])) bucket(ownerOfPath(p)).deleted++;
for (const p of (r.unaccounted_paths || [])) bucket(ownerOfPath(p)).unaccounted_paths.push(String(p));

let keys = Object.keys(byTenant);
if (!keys.length) { bucket(null); keys = Object.keys(byTenant); }

// Global, ownerless facts. A transport failure or an unrecognised response is a
// property of the ONE storage call, so it condemns every dealership's row --
// unverifiable is treated as FAILED, not as success, for all of them.
const extra = r.extra_returned || [];

return keys.map(k => {
  const b = byTenant[k];
  const N = b.requested;
  const M = b.deleted;
  const U = N - M;

  let status;
  if (r.transport_error || r.shape_unknown) status = 'FAILED';   // could not verify
  else if (N === 0)                         status = 'SUCCESS';  // nothing was due
  else if (M === 0)                         status = 'FAILED';
  else if (M === N)                         status = 'SUCCESS';
  else                                      status = 'PARTIAL';

  const parts = [];
  parts.push('Retention purge: requested ' + N + ', deleted ' + M + ', unaccounted ' + U
             + (r.oldest_due ? ' (oldest due ' + r.oldest_due + ')' : '') + '.');

  if (M > 0) {
    parts.push('purged_at written on ' + M + ' row(s) -- only the objects Supabase confirmed it deleted.');
  }

  if (U > 0) {
    // Absence from the delete response means NOT DELETED, never "fine". Name the
    // paths: this list is the whole point of the audit row. Only ever this
    // dealership's paths.
    const paths = b.unaccounted_paths.map(String);
    const shown = paths.slice(0, 20);
    parts.push('NOT deleted and deliberately NOT marked (still in the kyc-documents bucket, retried on the '
      + 'next run): ' + shown.join(', ')
      + (paths.length > shown.length ? ' ...and ' + (paths.length - shown.length) + ' more' : '') + '.');
  }

  if (M === 0 && N > 0) {
    parts.push('Storage confirmed ZERO deletions. Either the bulk delete failed, or these objects were '
      + 'already gone from an earlier half-completed run -- in which case these rows will be re-selected '
      + 'every night until a human verifies the files are absent and sets purged_at by hand. '
      + 'Check audit_log history for these paths before doing that.');
  }

  if (r.transport_error) {
    parts.push('Storage delete call errored: ' + r.transport_error);
  }
  if (r.shape_unknown) {
    parts.push('Storage answered with ' + r.returned_count + ' object name(s) in an unrecognised shape, so '
      + 'nothing could be reconciled and nothing was marked. Unverifiable is treated as FAILED, not as success.');
  }

  // An over-delete is not a success even when every requested path came back.
  // It is ownerless by definition -- we never asked for those objects -- so it
  // is reported on every dealership's row rather than guessed onto one.
  if (extra.length && status === 'SUCCESS') status = 'PARTIAL';
  if (extra.length) {
    parts.push('WARNING: Storage deleted ' + extra.length + ' object(s) that were NOT requested: '
      + extra.slice(0, 10).join(', ') + '. The delete was broader than intended -- investigate now.');
  }

  if (!b.tenant_id) {
    parts.push('TENANT UNRESOLVED: these kyc_documents rows carry no tenant_id, so this evidence is '
      + 'deliberately attributed to no dealership and is visible to service_role only.');
  }

  return { json: {
    workflow:    'NEXUS Retention Purge',
    status:      status,
    tenant_id:   b.tenant_id,
    requested:   N,
    deleted:     M,
    unaccounted: U,
    summary:     parts.join(' '),
  } };
});

// The KYC archive fails open on purpose — a Storage outage must not stop a
// customer getting their verdict. The cost is a row that claims no document.
// `purged_at IS NULL` distinguishes a genuine gap from a document we deleted on
// schedule. Anything here is a compliance hole, so it is worth a Slack ping.
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
if (rows.length === 0) return [];

const oldest = rows.map(r => r.created_at).sort()[0];
return [{ json: {
  count: rows.length,
  oldest: oldest,
  text: ':warning: *KYC archive gap* — ' + rows.length +
        ' document(s) in `kyc_documents` have no stored file ' +
        '(`storage_path IS NULL AND purged_at IS NULL`). Oldest: ' + oldest +
        '. The verdict was recorded but the image was never archived, so the ' +
        'retention record is incomplete for those customers.'
} }];

// Verify every node whose success this compliance row is about to claim.
//
// The old version asked only "does any item carry an .error key?". Supabase
// Storage's bulk delete never sets one for an object it failed to touch -- it
// simply LEAVES IT OUT. So the honest question is not "did the call error" but
// "did every requested path come back". ABSENCE FROM THE RESPONSE IS NOT
// SUCCESS. That comparison lives in `Reconcile Storage Deletions`; this node
// states its verdict on the row, in the repo's standard delivery shape.
//
// 2 Sep 2026: `Summarise Purge` now emits ONE ROW PER DEALERSHIP. The verdict
// below is a property of the single storage call, not of any one dealership, so
// it is computed once and attached to EVERY row. It must not collapse the input
// to the first item any more -- that would silently drop every dealership after
// the first from the compliance trail.
const r = $('Reconcile Storage Deletions').first().json || {};
const N = Number(r.requested) || 0;
const M = Number(r.deleted)   || 0;

const unverifiable = !!r.transport_error || !!r.shape_unknown;

const CLAIMED = [
  // The count claim itself, carried as an explicit verdict rather than a node
  // lookup -- no single node's output can answer it.
  // Critical (=> FAILED) when nothing at all was confirmed gone, or when the
  // response could not be reconciled. A partial shortfall is PARTIAL, and every
  // missing path is named in `summary`.
  { what: 'every requested KYC object confirmed gone from Storage (' + M + ' of ' + N + ')',
    critical: unverifiable || (M === 0 && N > 0),
    verdict: (!unverifiable && M === N)
      ? { ok: true }
      : { ok: false, why: unverifiable
            ? (r.transport_error
                ? 'delete call errored: ' + r.transport_error
                : 'response shape unrecognised, reconciliation impossible')
            : (N - M) + ' of ' + N + ' requested path(s) absent from the delete response - NOT deleted' } },

  { node: 'Delete Storage Objects', what: 'Storage bulk delete call completed', critical: true },

  // `prefixes` is the API's own parameter name. If Storage ever deleted by real
  // prefix it would destroy objects belonging to customers whose retention
  // period has not expired, and every requested path would still come back --
  // so a clean N-of-N is not on its own proof the delete was in scope.
  { what: 'delete stayed scoped to the requested paths',
    critical: false,
    verdict: ((r.extra_returned || []).length)
      ? { ok: false, why: r.extra_returned.length + ' object(s) deleted that were NOT requested: '
                          + r.extra_returned.slice(0, 10).join(', ') }
      : { ok: true } },
];

// Only claim the PATCH when the gate actually let it run -- claiming a node
// that was skipped by design would report a phantom drop.
// Non-critical: the delete already happened and is irreversible, and an
// unwritten purged_at self-heals - tomorrow's `Find Expired Documents` picks
// the row up again. It must still be NAMED, never hidden.
if (M > 0) {
  CLAIMED.push({ node: 'Mark Rows Purged',
                 what: 'purged_at written on ' + M + ' kyc_documents row(s)',
                 critical: false });
}

// Supabase's bulk delete answers with an ARRAY and n8n splits it into one item
// per object, so a transport failure can be item 7. Scan EVERY item, not item[0].
function check(c) {
  if (c.verdict) return { ...c, ok: c.verdict.ok, why: c.verdict.why };
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const bad = items.map(i => i.json || {}).filter(j => j.error !== undefined);
  if (bad.length) {
    const e = bad[0].error;
    const m = e && (e.message || e.description) || e;
    return { ...c, ok: false, why: bad.length + ' of ' + items.length + ' item(s) failed: ' + String(m).slice(0, 250) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(x => !x.ok);
const fatal   = dropped.filter(x => x.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

const delivery = {
  status,
  verified: results.filter(x => x.ok).map(x => x.what),
  dropped:  dropped.map(x => x.what + ' - ' + x.why),
  note: dropped.length
    ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
    : 'all ' + results.length + ' claimed steps verified',
};

return $input.all().map(it => ({ json: { ...(it.json || {}), delivery: delivery } }));

// -- Reconcile what Storage ACTUALLY deleted against what we asked it to -----
//
// THE ASSUMPTION THAT CAUSED THE BUG, WRITTEN DOWN SO NOBODY REPEATS IT:
//   Supabase Storage's bulk delete returns ONLY the objects it removed.
//   An object it could not touch is simply ABSENT from the response -- no
//   error key, no null, no placeholder. ABSENCE IS NOT SUCCESS. A path that
//   does not come back means "still sitting in the kyc-documents bucket", and
//   its kyc_documents row must stay UNMARKED so tomorrow's `Find Expired
//   Documents` selects it again. Unmarked self-heals. Wrongly-marked does not:
//   nothing ever looks at that row again while the customer's Emirates ID or
//   passport scan is still in the bucket.
//
// This node ALSO exists to collapse the response to exactly ONE item. n8n
// splits the returned array into one item per deleted object, and under
// executionOrder v1 that per-item fan-out is what let the old graph run
// `Mark Rows Purged` (which PATCHed all 500 REQUESTED ids, not the survivors)
// and `Log Purge to Audit` (SUCCESS) on output 0 before the failure branch on
// output 1 ever reached stopAndError. Nothing downstream of here can fan out
// per item, so that ordering hazard is structurally gone, not just counted
// differently.

const plan = $('Collect Expired Paths').first().json || {};

// `pairs` is the reconciliation ledger: the id that may be marked sits beside
// the path that must be confirmed gone first.
const pairs = Array.isArray(plan.pairs)
  ? plan.pairs
  // Defensive: if an older `Collect Expired Paths` is still deployed it emits
  // ids[] and paths[] but no pairs[]. Zip them rather than reconcile against
  // nothing, which would report every single row unaccounted.
  : (Array.isArray(plan.ids) && Array.isArray(plan.paths)
      ? plan.ids.map((id, i) => ({ id: id, path: plan.paths[i] }))
      : []);

const requested = pairs.length;
const items = $input.all().map(i => i.json || {});

// `Delete Storage Objects` runs onError:continueRegularOutput, so an HTTP or
// network failure arrives as an item carrying `error` rather than throwing.
const errItems = items.filter(j => j && j.error !== undefined);
let transport_error = null;
if (errItems.length) {
  const e = errItems[0].error;
  transport_error = String((e && (e.message || e.description)) || e).slice(0, 300);
}

// Normalise for COMPARISON ONLY. What we SEND to Storage is never rewritten --
// changing that would change which objects get destroyed.
const norm = p => String(p == null ? '' : p).replace(/^\/+/, '').replace(/^kyc-documents\//, '');

// Every object name Storage reported back as deleted.
const returned = [];
for (const j of items) {
  if (!j || j.error !== undefined) continue;
  if (typeof j.name === 'string' && j.name.length) returned.push(j.name);
}
const returnedSet = new Set();
for (const n of returned) { returnedSet.add(n); returnedSet.add(norm(n)); }

const confirmed = [];
const unaccounted = [];
for (const p of pairs) {
  const raw = String((p && p.path) || '');
  // Present in the response => confirmed gone => its id may be marked.
  // Missing from the response => NOT deleted => leave the row alone.
  if (raw && (returnedSet.has(raw) || returnedSet.has(norm(raw)))) confirmed.push(p);
  else unaccounted.push(p);
}

// Shape guard. If the response is non-empty, carries no error, and yet contains
// no `name` anywhere, the API contract changed under us and we CANNOT
// reconcile. Being unable to verify is not success either: mark nothing, fail
// loudly, let a human look. An empty `[]` body surfaces as `{}` here because
// the node runs with alwaysOutputData, so only keyed objects count as payload.
const payload = items.filter(j => j && j.error === undefined && Object.keys(j).length > 0);
const shape_unknown = !transport_error && payload.length > 0 && returned.length === 0;

// Paranoia. `prefixes` is the API's own parameter name. If Supabase ever
// applied real prefix semantics it would destroy MORE than we asked for.
// Nothing should ever come back that we did not request; if it does, the audit
// row has to say so.
const requestedSet = new Set();
for (const p of pairs) {
  const r = String((p && p.path) || '');
  requestedSet.add(r); requestedSet.add(norm(r));
}
const extra_returned = returned.filter(n => !requestedSet.has(n) && !requestedSet.has(norm(n)));

return [{ json: {
  requested:         requested,
  deleted:           confirmed.length,
  unaccounted:       unaccounted.length,
  confirmed_ids:     confirmed.map(p => p.id),
  confirmed_paths:   confirmed.map(p => p.path),
  unaccounted_paths: unaccounted.map(p => p.path),
  returned_count:    returned.length,
  extra_returned:    extra_returned,
  transport_error:   transport_error,
  shape_unknown:     shape_unknown,
  oldest_due:        plan.oldest_due || null,
} }];
